param([string]$Root=(Split-Path $PSScriptRoot -Parent))
Import-Module "$Root\Modules\Database.psm1" -Force;Import-Module "$Root\Modules\Core.psm1" -Force;$c=Get-Content "$Root\Config\AppConfig.json" -Raw|ConvertFrom-Json;Initialize-PlatformDatabase (Join-Path $Root $c.DatabasePath) "$Root\Database\Migrations" "$Root\Database\Seed" $c.SeedDatabase
foreach($j in DB "SELECT * FROM ScheduledReports WHERE Enabled=1 AND (NextRun IS NULL OR NextRun<=@n)" @{n=(Get-Date).ToString('s')}){try{$script:ReportFilters=if($j.FilterJson){$j.FilterJson|ConvertFrom-Json}else{@{Period=$c.DefaultReportPeriod}};$data=@(&$j.ReportPath);$out=if($j.OutputPath){$j.OutputPath}else{Join-Path $Root $c.ScheduledReportOutputFolder};New-Item $out -ItemType Directory -Force|Out-Null;$file=Join-Path $out ("$($j.Name)-$(Get-Date -Format yyyyMMdd-HHmmss).csv");$data|Export-Csv $file -NoTypeInformation;DB 'UPDATE ScheduledReports SET LastRun=@l,NextRun=@n WHERE Id=@i' @{l=(Get-Date).ToString('s');n=(Get-Date).AddDays(1).ToString('s');i=$j.Id}|Out-Null;Add-Audit 'Scheduled report' $j.Name Success $file}catch{Add-Audit 'Scheduled report' $j.Name Failed $_.Exception.Message}}
